let fs=require("fs"),path=require("path"),folderPath=path.resolve("./js");fs.readdir(folderPath,(e,r)=>{e||r.forEach(e=>{if(".js"===path.extname(e)&&!e.endsWith(".min.js")){var r=path.join(folderPath,e);let t=path.join(folderPath,e.replace(".js",".min.js"));fs.readFile(r,"utf8",(e,r)=>{e||(e=r.replace(/\s+/g," ").trim(),fs.writeFile(t,e,"utf8",e=>{}))})}})});